from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode

def apply_rewrite_rules(rules, urls):
    """
    指定された順序付きルールリストに基づいて、URLリストの各URLを書き換える関数。
    """
    processed_urls = []

    for url_str in urls:
        parsed_url = urlparse(url_str)
        matched = False

        for rule in rules:
            match_type = rule.get("match_type")
            match_value = rule.get("match_value")
            action = rule.get("action")
            action_value = rule.get("action_value")

            # 1. マッチング判定
            is_matched = False

            if match_type == "path_prefix":
                if parsed_url.path.startswith(match_value):
                    is_matched = True

            elif match_type == "host":
                host = parsed_url.hostname or ""
                if host == match_value:
                    is_matched = True
                elif match_value.startswith("*."):
                    suffix = match_value[2:]
                    # ドメインそのものは含まず、厳密なサブドメインであること
                    if host.endswith("." + suffix) and host != suffix:
                        is_matched = True

            elif match_type == "query_param":
                query_params = parse_qsl(parsed_url.query, keep_blank_values=True)
                # match_valueという名前のパラメータが存在するか確認
                if any(k == match_value for k, v in query_params):
                    is_matched = True

            # 2. アクションの適用
            if is_matched:
                matched = True

                # blockアクションの場合はNoneを返す
                if action == "block":
                    processed_urls.append(None)
                    break

                # 各アクションの処理
                if action == "strip_prefix":
                    path = parsed_url.path
                    if path.startswith(action_value):
                        path = path[len(action_value):]
                    if not path:
                        path = "/"
                    parsed_url = parsed_url._replace(path=path)

                elif action == "redirect_host":
                    # ホスト名部分を置換（ポート番号が含まれている場合は netloc 全体の処理に注意が必要だが、
                    # ここではホスト名のみを置き換える。ポート保持のため netloc を再構築する）
                    netloc = action_value
                    if parsed_url.port:
                        netloc = f"{action_value}:{parsed_url.port}"
                    # ユーザー情報（username/password）が含まれている場合も考慮
                    if parsed_url.username:
                        user_info = parsed_url.username
                        if parsed_url.password:
                            user_info += f":{parsed_url.password}"
                        netloc = f"{user_info}@{netloc}"
                    parsed_url = parsed_url._replace(netloc=netloc)

                elif action == "add_query_param":
                    # action_value は "key=value" の形式を想定
                    if "=" in action_value:
                        add_k, add_v = action_value.split("=", 1)
                    else:
                        add_k, add_v = action_value, ""

                    query_params = parse_qsl(parsed_url.query, keep_blank_values=True)
                    query_params.append((add_k, add_v))
                    new_query = urlencode(query_params)
                    parsed_url = parsed_url._replace(query=new_query)

                # 最初に適合したルールのみ適用してループを抜ける
                processed_urls.append(urlunparse(parsed_url))
                break

        # どのルールにも適合しなかった場合
        if not matched:
            processed_urls.append(url_str)

    return processed_urls
